const icon=(name,size=16)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.chart}</svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let preferences={theme:'dark',launch:false,notify:false,metric:'primary',interval:'5'};
try{preferences={...preferences,...JSON.parse(localStorage.getItem('usagebar-preview-preferences')||'{}')};}catch{}
const state={view:'overview',scenario:'normal',mode:'demo',period:'today',settings:'sources',busy:false,data:null,error:null,bucket:0,collapsed:false,expanded:false,search:'',model:'all',sessionPeriod:'today',sortNewest:true,sessionDetail:null};
const root=document.querySelector('#app-root');
const samples=[
  {id:'demo-session-a831',time:'14:28',project:'usagebar',model:'GPT-6.1 Sol',input:82400,output:5600,cache:89,day:'today'},
  {id:'demo-session-b940',time:'13:52',project:'api-service',model:'GPT-6 Luna',input:41600,output:3200,cache:82,day:'today'},
  {id:'demo-session-c107',time:'11:36',project:'usagebar',model:'GPT-6.1 Sol',input:136800,output:8700,cache:93,day:'today'},
  {id:'demo-session-d608',time:'10:17',project:'playground',model:'GPT-6 Luna',input:28300,output:1900,cache:76,day:'today'},
  {id:'demo-session-e390',time:'09:42',project:'api-service',model:'GPT-6.1 Sol',input:94600,output:6100,cache:87,day:'today'},
  {id:'demo-session-f182',time:'昨天 16:30',project:'playground',model:'GPT-6 Luna',input:60300,output:4100,cache:81,day:'week'},
];
let toastTimer;
function toast(message){const node=document.querySelector('#toast');node.textContent=message;node.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('visible'),3600);}
function save(){try{localStorage.setItem('usagebar-preview-preferences',JSON.stringify(preferences));}catch{}}
function setTheme(theme){preferences.theme=theme==='light'?'light':'dark';document.body.dataset.theme=preferences.theme;document.body.classList.toggle('light',preferences.theme==='light');document.querySelector('#theme-toggle').innerHTML=icon(preferences.theme==='dark'?'sun':'moon',17);save();}
function clock(epoch){return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(epoch*1000));}
function dateLabel(epoch){const date=new Date(epoch*1000);const day=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit'}).format(date);const today=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit'}).format(new Date());return `${day===today?'今天':day} ${clock(epoch)}`;}
function duration(mins){if(!mins)return '额度窗口';if(mins%1440===0)return `${mins/1440} 天窗口`;if(mins%60===0)return `${mins/60} 小时窗口`;return `${mins} 分钟窗口`;}
function shortDuration(mins){return !mins?'额度':mins%1440===0?`${mins/1440}d`:mins%60===0?`${mins/60}h`:`${mins}m`;}
function percent(value){if(value===null||value===undefined||!Number.isFinite(value))return '--';if(value>0&&value<1)return '<1';return String(Math.round(value*10)/10);}
function until(epoch){const m=Math.ceil((epoch*1000-Date.now())/60000);if(m<=0)return '等待确认重置';if(m<60)return `${m} 分钟后重置`;if(m<1440)return `${Math.floor(m/60)} 小时 ${m%60} 分后重置`;return `${Math.floor(m/1440)} 天后重置`;}
function ageText(stamp){const age=Math.max(0,Math.floor((Date.now()-new Date(stamp).getTime())/60000));return age<1?'刚刚更新':age<60?`${age} 分钟前更新`:`${Math.floor(age/60)} 小时前更新`;}
function demoData(){const low=state.scenario==='low';return {source:'demo',observedAt:new Date(Date.now()-(state.scenario==='stale'?43:2)*60000).toISOString(),account:{type:'chatgpt',planType:'plus',identityVerified:false},buckets:[{limitId:'codex',planType:'plus',primary:{usedPercent:low?94:9,remainingPercent:low?6:91,windowMinutes:300,resetsAt:Math.floor(Date.now()/1000)+4*3600+39*60},secondary:{usedPercent:low?97.5:41,remainingPercent:low?2.5:59,windowMinutes:10080,resetsAt:Math.floor(Date.now()/1000)+4*86400+21*3600+10*60}}]};}
function data(){return state.mode==='demo'?demoData():state.data;}
function bucket(){const d=data();return d?.buckets?.[state.bucket]||d?.buckets?.[0]||null;}
function windowState(window,stamp){if(!window||window.remainingPercent===null||window.remainingPercent===undefined)return 'unknown';if(window.invalid)return 'unknown';if(window.resetsAt&&Date.now()>=window.resetsAt*1000)return 'reset';const age=Date.now()-new Date(stamp).getTime();if(!Number.isFinite(age)||age< -60000)return 'unknown';if(age>3600000)return 'old';if(age>300000)return 'stale';return 'recent';}
function overallStatus(){if(state.mode==='demo'&&state.scenario==='disconnected')return 'disconnected';const d=data(),b=bucket();if(!b)return 'disconnected';const stamp=b.observedAt||d.observedAt;const states=[windowState(b.primary,stamp),windowState(b.secondary,stamp)];return states.some(s=>s==='reset')?'reset':states.every(s=>s==='unknown')?'unknown':states.some(s=>s==='stale'||s==='old')?'stale':'recent';}
function meter(value,count=36){return `<div class="quota-meter" aria-hidden="true">${Array.from({length:count},(_,i)=>`<span class="${value!==null&&i<count*value/100?'filled':''}"></span>`).join('')}</div>`;}
function quotaBlock(w,secondary=false){const d=data(),b=bucket(),stamp=b?.observedAt||d.observedAt;const status=windowState(w,stamp);const valid=['recent','stale'].includes(status);const remaining=valid?w.remainingPercent:null;const color=!valid?'var(--muted)':remaining<=5?'var(--danger)':remaining<=20?'var(--warning)':secondary?'var(--quota-secondary)':'var(--accent)';const reset=w?.resetsAt;return `<section class="quota-section ${secondary?'secondary':''}" style="--quota-color:${color};--secondary-quota-color:${color}"><div class="quota-title"><strong>${duration(w?.windowMinutes)}</strong><span class="reset-label">${icon('clock',11)}${reset?`${dateLabel(reset)} 重置`:'重置时间未知'}</span></div><div class="quota-numbers"><strong class="quota-number" style="color:${color}">${esc(percent(remaining))}${remaining!==null?'<span class="percent">%</span>':''}</strong><span class="remaining-label">剩余</span>${!secondary?`<span class="until-reset">${reset?esc(until(reset)):''}</span>`:''}</div>${meter(remaining,secondary?42:36)}<div class="quota-meta"><span>${valid?`已用 ${percent(w.usedPercent)}%`:status==='reset'?'预计重置时间已到，待确认':status==='old'?'快照较旧，请更新数据':'暂无有效快照'}</span><span>${secondary?'长周期额度':'短周期额度'}</span></div></section>`;}
function activity(){if(state.mode!=='demo'||state.scenario==='disconnected')return `<section class="activity-section"><div class="section-heading"><h3>Token 用量</h3><span class="demo-label">尚未接入</span></div><div class="empty-activity">${overallStatus()==='disconnected'?'连接后可先查看套餐额度。':'额度快照已独立展示。'}Token 趋势与会话统计将在后续接入。</div></section>`;const values={today:['1.42','86'],week:['9.86','88'],month:['32.7','87']}[state.period];return `<section class="activity-section"><div class="section-heading"><h3>用量概览</h3><div class="period-switch" aria-label="统计周期">${[['today','今日'],['week','本周'],['month','本月']].map(([id,label])=>`<button data-period="${id}" aria-pressed="${state.period===id}" class="${state.period===id?'selected':''}">${label}</button>`).join('')}</div></div><div class="activity-stats"><div class="activity-stat"><span>Token 总量</span><strong>${values[0]}<small>M</small></strong></div><div class="activity-stat"><span>缓存命中</span><strong>${values[1]}<small>%</small></strong></div></div><div class="mini-chart" aria-label="近7天 Token 演示趋势">${[28,52,39,71,58,87,66].map((h,i)=>`<div class="bar-column"><div class="bar" style="--bar-height:${h}%"></div><small>${i===6?'今天':14+i}</small></div>`).join('')}</div><div class="chart-label">近 7 天 · 演示数据</div></section>`;}
function overview(){const d=data(),b=bucket(),status=overallStatus();const connected=status!=='disconnected';const statusName={recent:state.mode==='live'?'已读取':'最近观测',stale:'数据过期',reset:'等待更新',unknown:'状态未知',disconnected:'未连接'}[status];const source=state.mode==='demo'?'演示快照':state.mode==='logs'?'本机日志 · 账号未核实':'Codex CLI 当前登录';const stamp=b?.observedAt||d?.observedAt;const plan=b?.planType||d?.account?.planType;return `<article class="popover"><header class="popover-header"><h2>UsageBar</h2><div class="header-tools"><span class="demo-label">${state.mode==='demo'?'演示数据':state.mode==='logs'?'本机快照':'服务商查询'}</span><button class="icon-button ${state.busy?'spinning':''}" data-action="refresh" aria-label="${state.mode==='demo'?'刷新演示':state.mode==='logs'?'重新扫描日志':'向服务商查询'}" ${state.busy?'disabled':''}>${icon('refresh',15)}</button></div></header><div class="account-row"><span class="provider-icon codex">${icon('terminal',18)}</span><div class="account-name"><strong>Codex</strong><small>${plan?`ChatGPT ${esc(plan.charAt(0).toUpperCase()+plan.slice(1))}`:'本机账号'}</small></div>${d?.buckets?.length>1?`<select class="bucket-select" aria-label="选择额度桶" id="bucket-select">${d.buckets.map((v,i)=>`<option value="${i}" ${state.bucket===i?'selected':''}>${esc(v.limitName||v.limitId)}</option>`).join('')}</select>`:''}<span class="account-status ${['stale','reset','unknown'].includes(status)?'warning':connected?'':'off'}">${statusName}</span></div>${connected?`${quotaBlock(b.primary)}${quotaBlock(b.secondary,true)}<div class="source-status">${icon(state.mode==='live'?'cloud':'shield',11)}<span>${ageText(stamp)}</span><span class="source-separator">·</span><span>${source}</span></div>${['stale','reset','unknown'].includes(status)?`<div class="stale-banner">${icon('alert',13)}<span>${status==='reset'?'预计重置时间已到，取得新快照后确认剩余额度。':status==='unknown'?'部分额度字段不可用，请更新快照后重试。':'这份快照已有一段时间，实际剩余额度可能已变化。'}</span></div>`:''}`:`<div class="empty-panel"><div class="empty-symbol">${icon('link',26)}</div><h3>让用量，回到视线之内</h3><p>连接本机 Codex，查看剩余额度<br>和下一次重置时间。</p><button class="primary-button" data-action="connect" ${state.busy?'disabled':''}>${state.busy?'正在检查…':'连接本机 Codex'}</button><button class="secondary-button" data-action="logs">读取日志</button></div>`}${state.error?`<div class="connection-inline">${esc(state.error.message)} ${state.mode!=='demo'?'保留上次成功的快照。':''}</div>`:''}${b?.otherLimitsPresent||b?.spendControlReached||b?.rateLimitReachedType?'<div class="connection-inline">账号存在其他使用限制，请同时查看服务商提示。</div>':''}${activity()}<div class="other-providers"><button class="provider-link" data-provider="claude"><span class="provider-mini claude">${icon('claude',17)}</span><span>Claude Code</span><span class="not-connected">未接入</span>${icon('chevron',12)}</button><button class="provider-link" data-provider="ark"><span class="provider-mini ark">${icon('ark',17)}</span><span>火山方舟</span><span class="not-connected">未接入</span>${icon('chevron',12)}</button></div><footer class="popover-footer"><button class="text-button" data-view="sessions">查看会话明细 ${icon('arrow',12)}</button><div class="footer-right"><button class="icon-button" data-view="settings" aria-label="打开设置">${icon('settings',15)}</button><button class="icon-button" data-action="close" aria-label="收起面板">${icon('power',14)}</button></div></footer></article>`;}
function chrome(title){return `<div class="window-toolbar"><div class="traffic-lights"><button data-action="window-close" aria-label="关闭窗口"></button><button data-action="window-minimize" aria-label="最小化窗口"></button><button data-action="window-expand" aria-label="调整窗口大小"></button></div><span class="window-title">${title}</span><div class="window-toolbar-right"><span class="demo-label">${state.mode==='demo'?'演示':'预览'}</span></div></div>`;}
function toggle(key,label){return `<button class="toggle" role="switch" aria-label="${label}" aria-checked="${!!preferences[key]}" data-toggle="${key}"><span></span></button>`;}
function settingsSources(){const d=data(),connected=state.mode==='live'&&!!d;const logs=state.mode==='logs'&&!!d;return `<h2>账号与数据源</h2><p class="settings-description">连接常用工具，把分散的用量放在一起。</p><div class="settings-group"><div class="settings-row"><span class="provider-icon codex">${icon('terminal',18)}</span><div class="settings-row-text"><strong>Codex 账号</strong><p>${connected?'已读取本机 CLI 当前登录账号的额度':'使用本机 Codex 管理的 ChatGPT 登录'}</p></div><button class="primary-button" data-action="connect" ${state.busy?'disabled':''}>${state.busy?'正在检查…':connected?'更新额度':'连接 Codex'}</button></div><div class="settings-row"><span class="provider-icon">${icon('folder',17)}</span><div class="settings-row-text"><strong>本机日志快照</strong><p>无需登录，展示最近一次观测到的额度</p></div><button class="secondary-button" data-action="logs" ${state.busy?'disabled':''}>${logs?'重新扫描':'读取快照'}</button></div></div>${state.busy?'<div class="connection-result loading-text"><span class="small-spinner"></span>正在检查本机 Codex 登录与额度，最多等待 25 秒。</div>':state.error?`<div class="connection-result error">${esc(state.error.message)}<br>${state.error.code==='auth_required'?'可在终端完成 Codex 登录后重试。<br><button data-action="copy-login">复制登录命令</button>':'可先读取本机日志快照，或在终端启动本地预览后重试。'}</div>`:connected||logs?`<div class="connection-result">${connected?'已取得服务商额度响应':'已读取本机日志快照'} · ${ageText(d.observedAt)}<br>${connected?`来源：Codex CLI 当前登录${d.account?.label?'（'+esc(d.account.label)+'）':''}。请确认这是要查看的账号。`:'账号归属未核实；日志快照可能落后于实际用量。'}</div>`:''}<div class="settings-group"><div class="settings-row"><span class="provider-icon" style="color:#c9a58f">${icon('claude',18)}</span><div class="settings-row-text"><strong>Claude Code</strong><p>本地日志与缓存用量</p></div><span class="demo-label">后续接入</span></div><div class="settings-row"><span class="provider-icon" style="color:#a9b9e1">${icon('ark',18)}</span><div class="settings-row-text"><strong>火山方舟</strong><p>API 用量与结算账单</p></div><span class="demo-label">后续接入</span></div></div><p class="settings-note icon-note">${icon('shield',13)}<span>账号登录由本机 Codex 管理。用量直接向服务商查询，不经过 UsageBar 自有服务器。</span></p>`;}
function settingsGeneral(){return `<h2>通用</h2><p class="settings-description">让 UsageBar 按你的习惯工作。</p><div class="settings-group"><div class="settings-row"><div class="settings-row-text"><strong>外观</strong><p>选择菜单栏面板与窗口的显示风格</p></div><select id="appearance" class="native-select" aria-label="外观"><option value="dark" ${preferences.theme==='dark'?'selected':''}>深色</option><option value="light" ${preferences.theme==='light'?'selected':''}>浅色</option></select></div><div class="settings-row"><div class="settings-row-text"><strong>登录时启动</strong><p>登录 macOS 后自动显示在菜单栏</p></div>${toggle('launch','登录时启动')}</div><div class="settings-row"><div class="settings-row-text"><strong>刷新间隔</strong><p>主动查询的目标间隔</p></div><select id="interval" class="native-select" aria-label="刷新间隔"><option value="1" ${preferences.interval==='1'?'selected':''}>1 分钟</option><option value="5" ${preferences.interval==='5'?'selected':''}>5 分钟</option><option value="15" ${preferences.interval==='15'?'selected':''}>15 分钟</option></select></div></div><p class="settings-note">原型中的开机启动与刷新间隔仅用于界面演示，不修改系统，也不启动后台定时查询。</p>`;}
function settingsDisplay(){return `<h2>显示与提醒</h2><p class="settings-description">只把最需要的信息留在菜单栏。</p><div class="settings-group"><div class="settings-row"><div class="settings-row-text"><strong>菜单栏显示</strong><p>各时间窗口的额度独立计算</p></div><select id="metric" class="native-select" aria-label="菜单栏指标"><option value="primary" ${preferences.metric==='primary'?'selected':''}>短周期剩余</option><option value="secondary" ${preferences.metric==='secondary'?'selected':''}>长周期剩余</option></select></div><div class="settings-row"><div class="settings-row-text"><strong>低额度提醒</strong><p>剩余不足 20% 时提醒</p></div>${toggle('notify','低额度提醒')}</div></div><p class="settings-note">提醒开关为交互演示，不申请通知权限。正式版只对有效的新快照提醒，过期快照不触发通知。</p>`;}
function settingsPrivacy(){return `<h2>数据与隐私</h2><p class="settings-description">本机保存，来源清楚。</p><div class="settings-group"><div class="settings-row">${icon('shield',18)}<div class="settings-row-text"><strong>用量元数据</strong><p>额度接口只返回窗口用量和重置时间。日志模式只提取额度字段，不保存对话正文。</p></div></div><div class="settings-row">${icon('database',18)}<div class="settings-row-text"><strong>原型偏好</strong><p>外观与演示开关保存在此浏览器，不保存账号凭证。</p></div><button class="secondary-button" data-action="clear">恢复默认</button></div></div><p class="settings-note">主动查询需要本机 Codex 与服务商通信。本机日志模式不会主动查询服务商。</p>`;}
function settings(){const tabs=[['general','monitor','通用'],['sources','link','账号与数据源'],['display','bell','显示与提醒'],['privacy','shield','数据与隐私']];const content={general:settingsGeneral,sources:settingsSources,display:settingsDisplay,privacy:settingsPrivacy}[state.settings]();return `<article class="native-window ${state.expanded?'expanded':''}">${chrome('UsageBar 设置')}<div class="window-body"><aside class="settings-sidebar">${tabs.map(([id,i,label])=>`<button data-settings="${id}" class="${state.settings===id?'selected':''}" title="${label}">${icon(i,16)}<span>${label}</span></button>`).join('')}<p class="sidebar-note">UsageBar 0.1<br>让用量一眼有数。</p></aside><section class="settings-content">${content}<div class="window-footnote"><span>界面偏好仅保存在此原型</span><span>macOS 菜单栏工具</span></div></section></div></article>`;}
function filteredSessions(){if(state.mode!=='demo')return [];const list=samples.filter(v=>(state.sessionPeriod!=='today'||v.day==='today')&&(state.model==='all'||v.model===state.model)&&v.project.toLowerCase().includes(state.search.toLowerCase()));return state.sortNewest?list:[...list].reverse();}
function k(n){return (n/1000).toFixed(1)+'K';}
function sessionTable(){const rows=filteredSessions();if(!rows.length)return `<div class="session-no-results">${state.mode!=='demo'?'本机模式尚未接入会话统计，额度已在菜单栏独立展示。':'没有符合筛选条件的会话。'}</div>`;return `<div class="session-table-wrap"><table class="session-table"><thead><tr><th><button class="sort-button" data-action="sort-time">时间 ${state.sortNewest?'↓':'↑'}</button></th><th>项目</th><th>模型</th><th class="numeric">输入 Token</th><th class="numeric">输出 Token</th><th class="numeric">缓存命中</th></tr></thead><tbody>${rows.map(v=>`<tr data-session="${v.id}" tabindex="0" aria-label="查看 ${v.project} 会话"><td>${v.time}</td><td class="project-cell">${v.project}</td><td><span class="model-chip">${v.model}</span></td><td class="numeric">${k(v.input)}</td><td class="numeric">${k(v.output)}</td><td class="numeric">${v.cache}%</td></tr>`).join('')}</tbody></table></div>`;}
function sessionSummary(){const rows=filteredSessions();return `<span>共 ${rows.length} 个${state.mode==='demo'?'演示':''}会话</span><span>输入 ${k(rows.reduce((a,v)=>a+v.input,0))} · 输出 ${k(rows.reduce((a,v)=>a+v.output,0))}</span>`;}
function sessions(){return `<article class="native-window sessions-window ${state.expanded?'expanded':''}">${chrome('会话明细')}<div class="window-body"><section class="session-content" style="width:100%"><div class="sessions-title"><div><h2>每一次调用，都有迹可循。</h2><p>${state.mode==='demo'?'以下为界面演示数据，不代表本机真实会话。':'本机模式仅展示已接入的额度数据。'}</p></div><button class="secondary-button" data-action="export" ${state.mode!=='demo'?'disabled':''}>${icon('download',13)}导出 CSV</button></div><div class="session-filters"><label class="search-field">${icon('search',13)}<input id="session-search" aria-label="搜索项目" placeholder="搜索项目" value="${esc(state.search)}"></label><select id="session-period" class="native-select" aria-label="会话日期"><option value="today" ${state.sessionPeriod==='today'?'selected':''}>今天</option><option value="week" ${state.sessionPeriod==='week'?'selected':''}>近 7 天</option><option value="month" ${state.sessionPeriod==='month'?'selected':''}>近 30 天</option></select><select id="session-model" class="native-select" aria-label="筛选模型"><option value="all">全部模型</option>${['GPT-6.1 Sol','GPT-6 Luna'].map(v=>`<option ${state.model===v?'selected':''}>${v}</option>`).join('')}</select></div><div id="session-table-area">${sessionTable()}</div>${state.sessionDetail?`<div class="session-detail"><span>演示会话 ID：${esc(state.sessionDetail)}</span><button class="text-button" data-action="copy-session">${icon('copy',12)}复制 ID</button></div>`:''}<div id="session-summary" class="session-summary">${sessionSummary()}</div></section></div></article>`;}
function anchorPopover(){const panel=document.querySelector('.popover');if(!panel)return;const menu=document.querySelector('#menu-indicator').getBoundingClientRect(),desk=document.querySelector('.desktop').getBoundingClientRect();const width=panel.getBoundingClientRect().width;const center=menu.left+menu.width/2;const right=Math.max(15,Math.min(desk.width-width-15,desk.right-center-width/2));panel.style.right=right+'px';const rect=panel.getBoundingClientRect();panel.style.setProperty('--arrow-right',(rect.right-center-6)+'px');}
function render(){root.innerHTML=state.collapsed?'':state.view==='settings'?settings():state.view==='sessions'?sessions():overview();document.querySelectorAll('.view-switch [data-view]').forEach(node=>{node.classList.toggle('selected',node.dataset.view===state.view);node.setAttribute('aria-pressed',String(node.dataset.view===state.view));});document.querySelectorAll('[data-scenario]').forEach(node=>{const selected=state.mode==='demo'&&node.dataset.scenario===state.scenario;node.disabled=state.busy;node.classList.toggle('selected',selected);node.setAttribute('aria-pressed',String(selected));node.querySelector('.scenario-check').innerHTML=selected?icon('check',12):'';});document.querySelector('.preview-inspector').classList.toggle('window-visible',state.view!=='overview');document.querySelector('#data-mode-label').textContent={demo:'当前为演示数据',logs:'当前为本机日志快照',live:'当前为服务商查询结果'}[state.mode];document.querySelector('#stage-mode').textContent=state.mode==='demo'?'所有数值均为示例，可在设置中连接本机':state.mode==='logs'?'本机日志快照 · 账号未核实':'真实额度查询 · Codex CLI 当前登录';const b=bucket(),w=b?.[preferences.metric]||b?.[preferences.metric==='primary'?'secondary':'primary'],s=overallStatus(),stamp=b?.observedAt||data()?.observedAt;const visible=s!=='disconnected'&&['recent','stale'].includes(windowState(w,stamp));document.querySelector('#menu-indicator').innerHTML=`<span class="menu-indicator-content">${icon('chart',13)}C ${visible?`${shortDuration(w.windowMinutes)} ${percent(w.remainingPercent)}%`:'--'}${icon('down',10)}</span>`;document.querySelector('#read-local').disabled=state.busy;document.querySelector('.mac-right time').textContent=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'numeric',day:'numeric',weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());requestAnimationFrame(anchorPopover);}
async function loadQuota(source){if(state.busy)return;state.busy=true;state.error=null;render();const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),26000);try{if(location.protocol==='file:')throw new Error('local_server_required');const response=await fetch(`/api/quota?source=${source}`,{signal:controller.signal,headers:{'X-UsageBar-Local':'preview'}});const value=await response.json();if(!value.ok){state.error=value.error||{message:'未取得新的额度。'};toast(state.error.message);}else{state.data=value;state.mode=value.source;state.bucket=Math.max(0,value.buckets.findIndex(v=>v.limitId==='codex'));state.scenario='normal';toast(source==='live'?'已读取本机 Codex 登录账号的额度':'已读取本机最近的额度快照');}}catch(error){state.error={code:'connection_failed',message:error.name==='AbortError'?'额度查询超时，可先读取本机日志。':'本机连接服务未运行，请通过 python3 scripts/preview_server.py 启动原型。'};toast(state.error.message);}finally{clearTimeout(timer);state.busy=false;render();}}
async function copy(text,message){try{await navigator.clipboard.writeText(text);toast(message);}catch{toast(`请手动复制：${text}`);}}
function exportCSV(){const rows=filteredSessions();const cell=v=>`"${String(v).replace(/"/g,'""')}"`;const lines=[['data_source','session_id','time','project','model','input_tokens','output_tokens','cache_hit_percent'],...rows.map(v=>['demo',v.id,v.time,v.project,v.model,v.input,v.output,v.cache])].map(row=>row.map(cell).join(',')).join('\r\n');const blob=new Blob(['\ufeff'+lines],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='usagebar-demo-sessions.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`已导出 ${rows.length} 个演示会话`);}
document.addEventListener('click',event=>{const node=event.target.closest('button,a');if(!node)return;if(node.matches('.preview-brand')){event.preventDefault();state.view='overview';state.collapsed=false;render();return;}if(node.id==='theme-toggle'){setTheme(preferences.theme==='dark'?'light':'dark');return;}if(node.id==='menu-indicator'){state.collapsed=state.view==='overview'?!state.collapsed:false;state.view='overview';render();return;}if(node.id==='read-local'){loadQuota('logs');return;}if(node.dataset.view){state.view=node.dataset.view;state.collapsed=false;render();return;}if(node.dataset.scenario){state.mode='demo';state.data=null;state.error=null;state.bucket=0;state.scenario=node.dataset.scenario;state.collapsed=false;state.view='overview';render();return;}if(node.dataset.period){state.period=node.dataset.period;render();return;}if(node.dataset.settings){state.settings=node.dataset.settings;render();return;}if(node.dataset.toggle){preferences[node.dataset.toggle]=!preferences[node.dataset.toggle];save();render();toast('已保存原型偏好，未修改系统设置');return;}if(node.dataset.provider){state.view='settings';state.settings='sources';state.collapsed=false;render();toast('该数据源将在后续版本接入');return;}const action=node.dataset.action;if(!action)return;if(action==='connect'){loadQuota('live');return;}if(action==='logs'){loadQuota('logs');return;}if(action==='refresh'){if(state.mode!=='demo'){loadQuota(state.mode);return;}state.busy=true;render();setTimeout(()=>{state.busy=false;render();toast('演示界面已刷新，未查询真实额度');},500);return;}if(action==='close'){state.collapsed=true;render();return;}if(action==='window-close'){state.view='overview';state.collapsed=false;render();return;}if(action==='window-minimize'){state.view='overview';state.collapsed=true;render();return;}if(action==='window-expand'){state.expanded=!state.expanded;render();return;}if(action==='copy-login'){copy('codex login','已复制 Codex 登录命令');return;}if(action==='copy-session'){copy(state.sessionDetail,'已复制演示会话 ID');return;}if(action==='export'){exportCSV();return;}if(action==='sort-time'){state.sortNewest=!state.sortNewest;render();return;}if(action==='clear'){preferences={theme:'dark',launch:false,notify:false,metric:'primary',interval:'5'};setTheme('dark');save();render();toast('已恢复原型默认偏好');}});
document.addEventListener('click',event=>{const row=event.target.closest('[data-session]');if(row){state.sessionDetail=row.dataset.session;render();}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if(state.view!=='overview'){state.view='overview';state.collapsed=false;}else{state.collapsed=true;}render();}if(event.key==='Enter'&&event.target.dataset.session){state.sessionDetail=event.target.dataset.session;render();}});
document.addEventListener('change',event=>{const {id,value}=event.target;if(id==='appearance'){setTheme(value);return;}if(id==='interval'){preferences.interval=value;save();toast('已保存演示刷新间隔，未启动后台查询');return;}if(id==='metric'){preferences.metric=value;save();render();return;}if(id==='bucket-select'){state.bucket=Number(value);render();return;}if(id==='session-period'){state.sessionPeriod=value;state.sessionDetail=null;render();return;}if(id==='session-model'){state.model=value;state.sessionDetail=null;render();}});
document.addEventListener('input',event=>{if(event.target.id==='session-search'){state.search=event.target.value;document.querySelector('#session-table-area').innerHTML=sessionTable();document.querySelector('#session-summary').innerHTML=sessionSummary();}});
document.querySelector('#system-icons').innerHTML=icon('wifi',14)+icon('battery',20);
setTheme(preferences.theme);render();
setInterval(()=>{if(state.mode!=='demo'&&state.view==='overview'&&!state.collapsed&&!state.busy)render();},60000);

window.addEventListener('resize',anchorPopover);
